3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects -> clients foreign key: H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the truncate and restore it immediately after.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
41	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
42	    }
43	
44	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
45	    @PostMapping("/seed")
46	    @SuppressWarnings("unchecked")
47	    public void seed(@RequestBody Map<String, Object> fixture) {
48	        List<Map<String, Object>> clients = (List<Map<String, Object>>) fixture.get("clients");
49	        if (clients != null) {
50	            for (Map<String, Object> client : clients) {
51	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
52	                jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
53	                        ((Number) client.get("id")).longValue(), client.get("name"),
54	                        client.get("email"));
55	            }
56	        }
57	        List<Map<String, Object>> projects = (List<Map<String, Object>>) fixture.get("projects");
58	        if (projects != null) {
59	            for (Map<String, Object> project : projects) {
60	                jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
61	                        ((Number) project.get("id")).longValue(), project.get("name"),
62	                        ((Number) project.get("clientId")).longValue());
63	            }
64	        }
65	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
66	        if (invoices != null) {
67	            for (Map<String, Object> invoice : invoices) {
68	                // status is optional in a fixture; default to UNPAID (matching Flyway V5) when absent.
69	                Object status = invoice.get("status");
70	                // issuedDate/dueDate are optional; fall back to the Flyway V7 column defaults when absent.
71	                Object issuedDate = invoice.get("issuedDate");
72	                Object dueDate = invoice.get("dueDate");
73	                jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
74	                        + " VALUES (?, ?, ?, ?, COALESCE(?, CURRENT_DATE),"
75	                        + " COALESCE(?, DATEADD('DAY', 30, CURRENT_DATE)))",
76	                        ((Number) invoice.get("id")).longValue(),
77	                        ((Number) invoice.get("projectId")).longValue(),
78	                        new java.math.BigDecimal(invoice.get("amount").toString()),
79	                        status != null ? status.toString() : "UNPAID",
80	                        issuedDate != null ? java.sql.Date.valueOf(issuedDate.toString()) : null,
81	                        dueDate != null ? java.sql.Date.valueOf(dueDate.toString()) : null);
82	            }
83	        }
84	    }
85	}
86

